import oracledb
from fastapi import Form, HTTPException
import os
import logging

async def login(id: str = Form(...), password: str = Form(...)):
    try:
        # 환경변수에서 DB 자격증명 로드 (보안 강화)
        connection = oracledb.connect(
            user=os.getenv("DB_USER"),
            password=os.getenv("DB_PASSWORD"),
            dsn=os.getenv("DB_DSN")
        )
        logging.info(f'Login attempt for user: {id}')  # 민감정보 제외한 로깅

        cursor = connection.cursor()
        cursor.execute(
            "SELECT * FROM userlist WHERE ID = :u_id AND PASSWORD = :u_pw",
            {"u_id": id, "u_pw": password}
        )
        result = cursor.fetchone()
        if result:
            logging.info(f"User logged in: {result[1]}")  # PII 노출 최소화
            return {"message": "로그인 성공", "user": {"id": result[1]}}
        else:
            return {"message": "로그인 실패"}
    except Exception as e:
        logging.error(f"Login error: {str(e)}")
        raise HTTPException(status_code=500, detail="서버 오류")
    finally:
        if 'connection' in locals():
            connection.close()
